# True for a domain function this loader can provide. Tests use it instead of
# `defined &subs::name`, which would be false until the module is loaded.
sub provides { return exists $DOMAIN_MODULE{ $_[0] // '' } }

# Load the module that provides $name without calling it. A test that replaces
# *subs::name with a local stub must do this first: the module defines the real
# sub when it loads and would otherwise overwrite the stub.
sub preload {
	my $name   = $_[0] // '';
	my $module = $DOMAIN_MODULE{$name} or return 0;
	(my $file = $module) =~ s{::}{/}g;
	require "$file.pm";
	return 1;
}

# Three subs are written one tab in at file scope in their module, so the
# column-0 scan below misses them; the module still defines them on load.
$DOMAIN_MODULE{$_} = 'JawnOS::Domain::Accounting' for qw(backfills);
$DOMAIN_MODULE{$_} = 'JawnOS::Domain::Sent' for qw(statement_preparer word_reader);

our $AUTOLOAD;
sub AUTOLOAD {
	my $name = $AUTOLOAD;
	return if $name eq 'subs::DESTROY';
	$name =~ s/.*:://;
	my $module = $DOMAIN_MODULE{$name}
		or die "Undefined subroutine &$AUTOLOAD called\n";
	(my $file = $module) =~ s{::}{/}g;
	require "$file.pm";
	die "&$AUTOLOAD is mapped to $module, which does not define $name\n"
		unless defined &$AUTOLOAD;
	goto &$AUTOLOAD;
}

1;
